-- =====================================================================
-- Kassa-databank met prijshistoriek  (MySQL 8)
-- Gegenereerd bestand: 19145 producten, 89364 prijsregels.
--
-- Prijzen worden nooit overschreven: elke prijswijziging is een nieuwe rij
-- in Prijs. Een prijs geldt vanaf GeldigVanaf (die dag inbegrepen) tot
-- GeldigTot (die dag niet meer: dan gaat de volgende prijs in). Bij de
-- laatste prijs van een product is GeldigTot leeg (NULL): geen einddatum.
-- Bedragen zijn exclusief btw. Aangekondigde prijzen hebben een
-- GeldigVanaf tussen 2027-09-06 en 2027-12-27.
-- =====================================================================

DROP DATABASE IF EXISTS kassa;
CREATE DATABASE kassa CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE kassa;
SET NAMES utf8mb4;

CREATE TABLE BtwTarief (
    BtwTariefId  INT          NOT NULL,
    Code         VARCHAR(10)  NOT NULL,
    Percentage   DECIMAL(5,2) NOT NULL,
    Omschrijving VARCHAR(50)  NOT NULL,
    CONSTRAINT PK_BtwTarief PRIMARY KEY (BtwTariefId),
    CONSTRAINT CK_BtwTarief_Percentage CHECK (Percentage BETWEEN 0 AND 100)
) ENGINE = InnoDB;

CREATE TABLE Categorie (
    CategorieId          INT         NOT NULL,
    Naam                 VARCHAR(50) NOT NULL,
    HoofdcategorieId     INT         NULL,
    StandaardBtwTariefId INT         NOT NULL,
    CONSTRAINT PK_Categorie PRIMARY KEY (CategorieId),
    CONSTRAINT FK_Categorie_Hoofdcategorie FOREIGN KEY (HoofdcategorieId) REFERENCES Categorie (CategorieId),
    CONSTRAINT FK_Categorie_BtwTarief FOREIGN KEY (StandaardBtwTariefId) REFERENCES BtwTarief (BtwTariefId)
) ENGINE = InnoDB;

CREATE TABLE Leverancier (
    LeverancierId INT         NOT NULL,
    Naam          VARCHAR(80) NOT NULL,
    BtwNummer     VARCHAR(14) NOT NULL,
    Gemeente      VARCHAR(50) NOT NULL,
    CONSTRAINT PK_Leverancier PRIMARY KEY (LeverancierId)
) ENGINE = InnoDB;

CREATE TABLE Product (
    ProductId    INT          NOT NULL,
    Ean          CHAR(13)     NOT NULL,
    Omschrijving VARCHAR(100) NOT NULL,
    Statiegeld   DECIMAL(5,2) NOT NULL DEFAULT 0,
    CategorieId  INT          NOT NULL,
    BtwTariefId  INT          NOT NULL,
    CONSTRAINT PK_Product PRIMARY KEY (ProductId),
    CONSTRAINT UQ_Product_Ean UNIQUE (Ean),
    CONSTRAINT FK_Product_Categorie FOREIGN KEY (CategorieId) REFERENCES Categorie (CategorieId),
    CONSTRAINT FK_Product_BtwTarief FOREIGN KEY (BtwTariefId) REFERENCES BtwTarief (BtwTariefId)
) ENGINE = InnoDB;

CREATE TABLE Prijs (
    ProductId     INT          NOT NULL,
    GeldigVanaf   DATE         NOT NULL,
    GeldigTot     DATE         NULL,
    BedragExclBtw DECIMAL(9,2) NOT NULL,
    CONSTRAINT PK_Prijs PRIMARY KEY (ProductId, GeldigVanaf),
    CONSTRAINT FK_Prijs_Product FOREIGN KEY (ProductId) REFERENCES Product (ProductId),
    CONSTRAINT CK_Prijs_Bedrag CHECK (BedragExclBtw >= 0),
    CONSTRAINT CK_Prijs_Periode CHECK (GeldigTot IS NULL OR GeldigTot > GeldigVanaf)
) ENGINE = InnoDB;

CREATE TABLE Leveringsartikel (
    LeverancierId       INT          NOT NULL,
    ProductId           INT          NOT NULL,
    Bestelcode          VARCHAR(20)  NOT NULL,
    AankoopprijsExclBtw DECIMAL(9,2) NOT NULL,
    Verpakkingseenheid  INT          NOT NULL,
    CONSTRAINT PK_Leveringsartikel PRIMARY KEY (LeverancierId, ProductId),
    CONSTRAINT FK_Leveringsartikel_Leverancier FOREIGN KEY (LeverancierId) REFERENCES Leverancier (LeverancierId),
    CONSTRAINT FK_Leveringsartikel_Product FOREIGN KEY (ProductId) REFERENCES Product (ProductId)
) ENGINE = InnoDB;

CREATE TABLE Actie (
    ActieId            INT          NOT NULL,
    ProductId          INT          NOT NULL,
    Omschrijving       VARCHAR(60)  NOT NULL,
    Kortingspercentage DECIMAL(5,2) NOT NULL,
    Van                DATE         NOT NULL,
    Tot                DATE         NOT NULL,
    CONSTRAINT PK_Actie PRIMARY KEY (ActieId),
    CONSTRAINT FK_Actie_Product FOREIGN KEY (ProductId) REFERENCES Product (ProductId)
) ENGINE = InnoDB;

SET autocommit = 0;








COMMIT;
SET autocommit = 1;
